use vstd::prelude::*;

verus! {

/// Spec-level description of the intersperse result as a sequence.
spec fn intersperse_seq(s: Seq<i32>, delim: i32) -> Seq<i32> {
    if s.len() == 0 {
        Seq::<i32>::empty()
    } else {
        Seq::<i32>::new(2 * s.len() - 1, |i: int|
            if i % 2 == 0 {
                s[i / 2]
            } else {
                delim
            }
        )
    }
}

fn intersperse(numbers: &[i32], delim: i32) -> (res: Vec<i32>)
    ensures
        res@ == intersperse_seq(numbers@, delim),
{
    let n = numbers.len();

    // Empty input => empty output.
    if n == 0 {
        return Vec::new();
    }

    // Non-empty case.
    let mut res: Vec<i32> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            n == numbers.len(),
            0 <= i <= n,
            n > 0,
            // Length matches: for i processed elements, we have 2i elements if i<n, else 2n-1.
            res@.len() == if i < n { 2 * i as int } else { 2 * n as int - 1 },
            // Content matches the intended prefix:
            // - even positions are the already-copied input elements
            // - odd positions are delimiters, but only between copied elements
            forall|k: int|
                0 <= k < res@.len() ==>
                (
                    if k % 2 == 0 {
                        // must refer to an already processed input element
                        k / 2 < i as int && res@[k] == numbers@[k / 2]
                    } else {
                        // delimiters exist only when there is an element after the previous one
                        (k + 1) / 2 < i as int && res@[k] == delim
                    }
                ),
        decreases n - i,
    {
        // Append the next original element
        res.push(numbers[i]);

        // If not the last element, append delimiter (no trailing delimiter).
        if i + 1 < n {
            res.push(delim);
        }

        i = i + 1;
    }

    // At loop end, i == n, so res should match the full spec sequence.
    assert(i == n);
    assert(res@.len() == 2 * n as int - 1);

    // Prove pointwise equality to the spec characterization.
    assert forall|k: int| 0 <= k < res@.len() implies res@[k] == intersperse_seq(numbers@, delim)[k] by {
        // From the invariants at i == n:
        // - for even k: res[k] == numbers[k/2]
        // - for odd k:  res[k] == delim
        // and this matches intersperse_seq construction.
    };

    assert(res@ == intersperse_seq(numbers@, delim));
    res
}

} // verus!

